func TestCheckAddress() {
	exchange := ccxt.NewExchange().(*ccxt.Exchange)
	exchange.DerivedExchange = exchange
	exchange.InitParent(map[string]any{
		"id": "sampleexchange",
	}, map[string]any{}, exchange)
	var address string = "rDsbeomae4FXwgQTJp9Rs64Qg9vDiTCdBv"
	// currencies without a tag requirement pass with or without a tag
	Assert(ccxt.IsEqual(exchange.CheckAddress(address), address))
	Assert(ccxt.IsEqual(exchange.CheckAddress(address, "BTC"), address))
	// tag-required currencies need a tag
	Assert(ccxt.IsEqual(exchange.CheckAddress(address, "XRP", "123456"), address))
	Assert(ccxt.IsEqual(exchange.CheckAddress(address, "ATOM", "123456"), address))
	var caught bool = false

	{
		func() (ret_ any) {
			defer func() {
				if error := recover(); error != nil {
					if error == "break" {
						return
					}
					ret_ = func() any {
						// catch block:
						caught = true
						return nil
					}()
				}
			}()
			// try block:
			exchange.CheckAddress(address, "XRP")
			return nil
		}()

	}
	assert(caught, "XRP without a tag should have thrown")
	caught = false

	{
		func() (ret_ any) {
			defer func() {
				if error := recover(); error != nil {
					if error == "break" {
						return
					}
					ret_ = func() any {
						// catch block:
						caught = true
						return nil
					}()
				}
			}()
			// try block:
			exchange.CheckAddress(address, "XLM", nil)
			return nil
		}()

	}
	assert(caught, "XLM without a tag should have thrown")
	caught = false

	{
		func() (ret_ any) {
			defer func() {
				if error := recover(); error != nil {
					if error == "break" {
						return
					}
					ret_ = func() any {
						// catch block:
						caught = true
						return nil
					}()
				}
			}()
			// try block:
			exchange.CheckAddress(nil, "BTC")
			return nil
		}()

	}
	assert(caught, "an undefined address should have thrown")
}
